<section class="section"><header class="admin-header"><h1>Usuarios administrativos</h1><a href="user_create.php" class="btn">Nuevo usuario</a></header><?php if (!empty($error)): ?><p class="alert alert--error"><?php echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></p><?php endif; ?><?php if (!$editing): ?><table class="table"><thead><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($users as $item): ?><tr><td><?php echo htmlspecialchars($item->username, ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo htmlspecialchars($item->displayName, ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo htmlspecialchars($item->role, ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo $item->active ? 'Activo' : 'Inactivo'; ?></td><td><a href="user_edit.php?id=<?php echo $item->id; ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table><?php else: ?><form method="post" class="admin-form"><label>Usuario<input name="username" required value="<?php echo htmlspecialchars($user['username'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Nombre visible<input name="display_name" value="<?php echo htmlspecialchars($user['display_name'] ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Rol<select name="role"><option value="agent">Operador</option><option value="admin" <?php echo ($user['role'] ?? '') === 'admin' ? 'selected' : ''; ?>>Administrador</option></select></label><label>Contraseña<input type="password" name="password" <?php echo $user ? '' : 'required'; ?>></label><label><input type="checkbox" name="active" <?php echo ($user['active'] ?? 1) ? 'checked' : ''; ?>> Activo</label><button class="btn">Guardar</button></form><?php endif; ?></section>
